import { useMemo, useState } from "react";

export type Column<T> = {
  key: keyof T & string;
  label: string;
  align?: "left" | "right";
  render?: (row: T) => React.ReactNode;
};

export function DataExplorerTable<T extends { id: string }>({
  rows,
  columns,
  onBulkAction,
}: {
  rows: T[];
  columns: Column<T>[];
  onBulkAction?: (ids: string[], action: string) => void;
}) {
  const [sortKey, setSortKey] = useState<string | null>(null);
  const [asc, setAsc] = useState(true);
  const [selected, setSelected] = useState<Set<string>>(new Set());

  const ordered = useMemo(() => {
    if (!sortKey) return rows;
    return [...rows].sort((a, b) => {
      const av = String(a[sortKey as keyof T] ?? "");
      const bv = String(b[sortKey as keyof T] ?? "");
      return asc ? av.localeCompare(bv) : bv.localeCompare(av);
    });
  }, [rows, sortKey, asc]);

  const toggleRow = (id: string) =>
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  const allSelected = ordered.length > 0 && selected.size === ordered.length;

  return (
    <div className="dex-root">
      {selected.size > 0 ? (
        <div className="dex-bulk" role="toolbar" aria-label="Bulk actions">
          <span>{selected.size} selected</span>
          <button type="button" onClick={() => onBulkAction?.([...selected], "export")}>
            Export
          </button>
          <button type="button" onClick={() => setSelected(new Set())}>
            Clear
          </button>
        </div>
      ) : null}

      <div className="dex-scroll">
        <table>
          <thead>
            <tr>
              <th scope="col" className="dex-check">
                <input
                  type="checkbox"
                  checked={allSelected}
                  aria-label="Select all rows"
                  onChange={() =>
                    setSelected(allSelected ? new Set() : new Set(ordered.map((r) => r.id)))
                  }
                />
              </th>
              {columns.map((col) => (
                <th
                  key={col.key}
                  scope="col"
                  data-align={col.align ?? "left"}
                  aria-sort={sortKey === col.key ? (asc ? "ascending" : "descending") : "none"}
                >
                  <button
                    type="button"
                    onClick={() => {
                      setSortKey(col.key);
                      setAsc(sortKey === col.key ? !asc : true);
                    }}
                  >
                    {col.label}
                    {sortKey === col.key ? (asc ? " ↑" : " ↓") : ""}
                  </button>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {ordered.map((row) => (
              <tr key={row.id} data-selected={selected.has(row.id)}>
                <td className="dex-check">
                  <input
                    type="checkbox"
                    checked={selected.has(row.id)}
                    aria-label={"Select " + row.id}
                    onChange={() => toggleRow(row.id)}
                  />
                </td>
                {columns.map((col) => (
                  <td key={col.key} data-align={col.align ?? "left"}>
                    {col.render ? col.render(row) : String(row[col.key] ?? "")}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>

        {ordered.length === 0 ? (
          <p className="dex-empty">No rows matched the current query.</p>
        ) : null}
      </div>
    </div>
  );
}

