.dex-root {
  display: flex;
  flex-direction: column;
  min-height: 240px;
  border: 1px solid var(--line-subtle, #e4e4e7);
  border-radius: 8px;
  overflow: hidden;
  background: var(--surface-base, #ffffff);
  font-size: 12px;
  color: var(--text-strong, #18181b);
}
.dex-bulk {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 12px;
  background: var(--accent-soft, rgba(99, 102, 241, 0.12));
  border-bottom: 1px solid var(--line-subtle, #e4e4e7);
}
.dex-bulk button {
  font: inherit;
  padding: 2px 9px;
  border-radius: 5px;
  border: 1px solid var(--line-strong, #a1a1aa);
  background: var(--surface-base, #ffffff);
  cursor: pointer;
}
.dex-scroll {
  flex: 1;
  overflow: auto;
}
.dex-root table {
  width: 100%;
  border-collapse: collapse;
}
.dex-root thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 0;
  background: var(--surface-inset, #f4f4f5);
  border-bottom: 1px solid var(--line-subtle, #e4e4e7);
  text-align: left;
  white-space: nowrap;
}
.dex-root thead button {
  width: 100%;
  padding: 7px 10px;
  font: inherit;
  font-weight: 600;
  text-align: inherit;
  border: none;
  background: none;
  color: inherit;
  cursor: pointer;
}
.dex-root td {
  padding: 6px 10px;
  border-bottom: 1px solid var(--line-subtle, #f1f1f3);
  max-width: 320px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.dex-root [data-align='right'] {
  text-align: right;
}
.dex-root tbody tr[data-selected='true'] {
  background: var(--accent-soft, rgba(99, 102, 241, 0.08));
}
.dex-root tbody tr:hover {
  background: var(--surface-inset, #fafafa);
}
.dex-check {
  width: 34px;
  text-align: center;
}
.dex-empty {
  margin: 0;
  padding: 32px 12px;
  text-align: center;
  color: var(--text-muted, #71717a);
}
